    else if (l.startsWith("+")) r.push(l.slice(2));
    else { e.push(l.slice(2)); r.push(l.slice(2)); }
  }
  while (e.length && r.length && e[e.length - 1] === "" && r[r.length - 1] === "") { e.pop(); r.pop(); }
  pairs.push([e.join("\n"), r.join("\n")]);
  i = j;
}
let shown = 0;
for (const [e, r] of pairs) {
